# But I need to apply this to the full 24x25 grid

def apply_transform(grid):
    result = [[0]*len(row) for row in grid]
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == 6:
                result[r][c] = 6
